import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';
import '../css/ReportComponent.css';

class ReportComponent extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      fromDate: '2026-10-01',
      toDate: '2026-11-01',
      stats: { revenue: 0, orders: 0, customers: 0, products: 0 },
      chartData: [],
      tableRequests: [],
      topProducts: []
    };
  }

  componentDidMount() {
    this.apiGetReports();
  }

  apiGetReports = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/reports', config).then((res) => {
      if (res.data) {
        this.setState({
          stats: {
            revenue: res.data.revenue || 0,
            orders: res.data.orders || 0,
            customers: res.data.customers || 0,
            products: res.data.products || 0
          },
          chartData: res.data.chartData || [],
          tableRequests: res.data.tableRequests || [],
          topProducts: res.data.topProducts || []
        });
      }
    }).catch(err => {
      console.error("Lỗi tải báo cáo:", err);
    });
  };

  btnFilterClick = (e) => {
    e.preventDefault();
    this.apiGetReports();
  };

  render() {
    const { fromDate, toDate, stats, chartData, tableRequests, topProducts } = this.state;

    const safeChartData = Array.isArray(chartData) ? chartData : [];

    const maxRevenue = Math.max(...safeChartData.map(item => item.revenue), 1000000);
    const points = safeChartData.map((item, index) => {
      const x = (index / (safeChartData.length - 1 || 1)) * 500;
      const y = 160 - (item.revenue / maxRevenue) * 130;
      return `${x},${y}`;
    }).join(' ');

    return (
      <div className="report-container">
        <h3 className="report-title">HỆ THỐNG BÁO CÁO & THỐNG KÊ</h3>

        {/* 1. Bộ lọc thời gian */}
        <div className="filter-bar">
          <span><b>Đơn hàng từ:</b></span>
          <input
            type="date"
            className="filter-input"
            value={fromDate}
            onChange={(e) => this.setState({ fromDate: e.target.value })}
          />
          <span><b>đến</b></span>
          <input
            type="date"
            className="filter-input"
            value={toDate}
            onChange={(e) => this.setState({ toDate: e.target.value })}
          />
          <button className="filter-btn" onClick={this.btnFilterClick}>
            Lọc dữ liệu
          </button>
        </div>

        {/* 2. Thẻ thống kê tổng quan */}
        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-title">Doanh thu</div>
            <div className="stat-value" style={{ color: '#2E7D32' }}>
              {(stats.revenue || 0).toLocaleString('vi-VN')} đ
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-title">Đơn hàng</div>
            <div className="stat-value" style={{ color: '#1E88E5' }}>{stats.orders || 0} đơn</div>
          </div>
          <div className="stat-card">
            <div className="stat-title">Khách hàng</div>
            <div className="stat-value" style={{ color: '#C85A32' }}>{stats.customers || 0} khách</div>
          </div>
          <div className="stat-card">
            <div className="stat-title">Sản phẩm</div>
            <div className="stat-value" style={{ color: '#6A1B9A' }}>{stats.products || 0} món</div>
          </div>
        </div>

        {/* 3. Biểu đồ đường & Yêu cầu bàn */}
        <div className="content-row">
          <div className="chart-box">
            <h4 style={{ marginBottom: '15px' }}>Biểu đồ xu hướng doanh thu</h4>
            <div style={{ position: 'relative', height: '180px', width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              {safeChartData.length === 0 ? (
                <div style={{ color: '#888', fontStyle: 'italic' }}>Chưa có đủ dữ liệu đơn hàng để vẽ biểu đồ.</div>
              ) : (
                <svg viewBox="0 0 500 180" style={{ width: '100%', height: '100%', overflow: 'visible' }}>
                  <polyline
                    fill="none"
                    stroke="#C85A32"
                    strokeWidth="3"
                    points={points}
                  />
                  {safeChartData.map((item, index) => {
                    const x = (index / (safeChartData.length - 1 || 1)) * 500;
                    const y = 160 - (item.revenue / maxRevenue) * 130;
                    return (
                      <g key={index}>
                        <circle cx={x} cy={y} r="5" fill="#4A2E2B" />
                        <text x={x} y="178" fontSize="11" textAnchor="middle" fill="#666">{item._id}</text>
                      </g>
                    );
                  })}
                </svg>
              )}
            </div>
          </div>

          <div className="notification-box">
            <h4 style={{ marginBottom: '15px', color: '#4A2E2B' }}>Yêu cầu từ bàn</h4>
            <div style={{ fontSize: '13px', lineHeight: '1.8' }}>
              {(!tableRequests || tableRequests.length === 0) ? (
                <div style={{ color: '#888', fontStyle: 'italic' }}>Không có yêu cầu mới nào.</div>
              ) : (
                tableRequests.map((req) => (
                  <div key={req._id} className={req.content && req.content.includes('thanh toán') ? 'notif-item-payment' : 'notif-item-service'}>
                    <b>Bàn {req.tableNo}:</b> {req.content}
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        {/* 4. Top sản phẩm bán chạy nhất */}
        <div className="top-products-box">
          <h4 style={{ marginBottom: '15px' }}>Top sản phẩm bán chạy nhất</h4>
          <div className="top-products-grid">
            {(!topProducts || topProducts.length === 0) ? (
              <div style={{ color: '#888', fontStyle: 'italic' }}>Chưa có dữ liệu bán hàng.</div>
            ) : (
              topProducts.map((item, index) => (
                <div key={item._id || index} className="product-item">
                  {item.image ? (
                    <img src={item.image} alt={item.name} className="product-img" />
                  ) : (
                    <div className="product-placeholder">#{index + 1}</div>
                  )}
                  <div>
                    <div style={{ fontWeight: 'bold', fontSize: '14px' }}>{item.name}</div>
                    <div style={{ color: '#C85A32', fontSize: '13px', fontWeight: 'bold' }}>
                      {(item.price || 0).toLocaleString('vi-VN')} đ
                    </div>
                    <div style={{ fontSize: '11px', color: '#666' }}>Đã bán: {item.totalSold || 0} phần</div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

      </div>
    );
  }
}

export default ReportComponent;
